option.value:
locals {
  vip_ip       = cidrhost(var.talos_network.subnet, 2)
  cp_network   = cidrsubnet(var.talos_network.subnet, 2, 0)
  node_network = cidrsubnet(var.talos_network.subnet, 2, 1)
}

data "talos_machine_configuration" "controller" {
  count            = var.talos_control_plane.nodes
  cluster_name     = var.cluster_name
  cluster_endpoint = "https://${local.vip_ip}:6443"
  machine_secrets  = talos_machine_secrets.talos.machine_secrets
  machine_type     = "controlplane"
  talos_version    = "v${var.talos_control_plane.version}"
  config_patches = [
    # Document 1: Core Machine/Cluster Logic (No interface list here)
    yamlencode({
      cluster = {
        extraManifests = ["https://raw.githubusercontent.com/alex1989hu/kubelet-serving-cert-approver/refs/tags/v0.10.3/deploy/standalone-install.yaml"]
        proxy   = { disabled = true }
        network = { cni = { name = "none" } }
      }
      machine = {
        kubelet = {
          extraArgs = { "rotate-server-certificates" = "true" }
          nodeIP    = { validSubnets = [cidrsubnet(var.talos_network.subnet, 0, 0)] }
        }
      }
    }),

    # Document 2: The VIP Resource
    yamlencode({
      version = "v1alpha1"
      kind    = "VirtualIPConfig"
      metadata = { name = "controlplane-vip" }
      spec = {
        interface = "eth0"
        ip        = local.vip_ip
      }
    }),
    yamlencode({
      version = "v1alpha1"
      kind    = "AddressConfig"
      metadata = { name = "eth0-static-ip" }
      spec = {
        interface = "eth0"
        addresses = ["${cidrhost(local.cp_network, count.index + 3)}/${var.talos_network.subnet_cidr}"]
      }
    }),

    # Document 3: Static IP for eth1 using AddressConfig
    yamlencode({
      version = "v1alpha1"
      kind    = "AddressConfig"
      metadata = { name = "eth1-static-ip" }
      spec = {
        interface = "eth1"
        addresses = ["${cidrhost(var.talos_control_plane.cluster_subnet, count.index + 3)}/${var.talos_control_plane.cluster_subnet_cidr}"]
      }
    })
  ]
}

resource "talos_machine_configuration_apply" "control_plane" {
  count                       = var.talos_control_plane.nodes
  client_configuration        = talos_machine_secrets.talos.client_configuration
  machine_configuration_input = data.talos_machine_configuration.controller[count.index].machine_configuration
  node                        = cidrhost(local.cp_network, count.index + 3)
}

resource "talos_machine_bootstrap" "control_plane" {
  depends_on = [
    talos_machine_configuration_apply.control_plane
  ]
  node                 = cidrhost(local.cp_network, 3)
  client_configuration = talos_machine_secrets.talos.client_configuration
}

resource "talos_cluster_kubeconfig" "this" {
  depends_on = [
    talos_machine_bootstrap.control_plane
  ]
  client_configuration = talos_machine_secrets.talos.client_configuration
  node                 = local.vip_ip
}

locals {
  vip_ip       = cidrhost(var.talos_network.subnet, 2)
  cp_network   = cidrsubnet(var.talos_network.subnet, 2, 0)
  node_network = cidrsubnet(var.talos_network.subnet, 2, 1)
}

data "talos_machine_configuration" "controller" {
  count            = var.talos_control_plane.nodes
  cluster_name     = var.cluster_name
  cluster_endpoint = "https://${local.vip_ip}:6443"
  machine_secrets  = talos_machine_secrets.talos.machine_secrets
  machine_type     = "controlplane"
  talos_version    = "v${var.talos_control_plane.version}"
  config_patches = [
    # Document 1: Core Machine/Cluster Logic (No interface list here)
    yamlencode({
      cluster = {
        extraManifests = ["https://raw.githubusercontent.com/alex1989hu/kubelet-serving-cert-approver/refs/tags/v0.10.3/deploy/standalone-install.yaml"]
        proxy   = { disabled = true }
        network = { cni = { name = "none" } }
      }
      machine = {
        kubelet = {
          extraArgs = { "rotate-server-certificates" = "true" }
          nodeIP    = { validSubnets = [cidrsubnet(var.talos_network.subnet, 0, 0)] }
        }
      }
    }),

    # Document 2: The VIP Resource
    yamlencode({
      version = "v1alpha1"
      kind    = "VirtualIPConfig"
      metadata = { name = "controlplane-vip" }
      spec = {
        interface = "eth0"
        ip        = local.vip_ip
      }
    }),
    yamlencode({
      version = "v1alpha1"
      kind    = "AddressConfig"
      metadata = { name = "eth0-static-ip" }
      spec = {
        interface = "eth0"
        addresses = ["${cidrhost(local.cp_network, count.index + 3)}/${split("/", local.cp_network)[1]}"]
      }
    }),

    # Default route so the control plane can reach the gateway after reboot
    yamlencode({
      version  = "v1alpha1"
      kind     = "RouteConfig"
      metadata = { name = "eth0-default-route" }
      spec = {
        gateway     = var.network_config.gateway
        network     = "0.0.0.0/0"
        outLinkName = "eth0"
      }
    }),

    # Document 3: Static IP for eth1 using AddressConfig
    yamlencode({
      version = "v1alpha1"
      kind    = "AddressConfig"
      metadata = { name = "eth1-static-ip" }
      spec = {
        interface = "eth1"
        addresses = ["${cidrhost(var.talos_control_plane.cluster_subnet, count.index + 3)}/${var.talos_control_plane.cluster_subnet_cidr}"]
      }
    })
  ]
}

resource "talos_machine_configuration_apply" "control_plane" {
  count                       = var.talos_control_plane.nodes
  client_configuration        = talos_machine_secrets.talos.client_configuration
  machine_configuration_input = data.talos_machine_configuration.controller[count.index].machine_configuration
  node                        = cidrhost(local.cp_network, count.index + 3)
}

resource "talos_machine_bootstrap" "control_plane" {
  depends_on = [
    talos_machine_configuration_apply.control_plane
  ]
  node                 = cidrhost(local.cp_network, 3)
  client_configuration = talos_machine_secrets.talos.client_configuration
}

resource "talos_cluster_kubeconfig" "this" {
  depends_on = [
    talos_machine_bootstrap.control_plane
  ]
  client_configuration = talos_machine_secrets.talos.client_configuration
  node                 = local.vip_ip
}
